method get_max_triples(n: int) returns (count: int)
    requires n > 0
    ensures count >= 0
    ensures count == CountValidTriples(a)
{
    var a := new int[n];
    var i: int;
    var j: int;
    var k: int;

    // Populate the array a according to the definition
    for i := 1 to n {
        a[i - 1] := i * i - i + 1;
    }

    count := 0;

    // Count the valid triples (a[i], a[j], a[k]) where i < j < k
    for i := 0 to n - 1 {
        for j := i + 1 to n - 1 {
            for k := j + 1 to n - 1 {
                if (a[i] + a[j] + a[k]) % 3 == 0 {
                    count := count + 1;
                }
            }
        }
    }
    // Return the count of valid triples
}

function CountValidTriples(a: array<int>) : int
    requires a.Length > 0
    ensures result >= 0
{
    var count := 0;
    var i: int;
    var j: int;
    var k: int;

    for i := 0 to a.Length - 1 {
        for j := i + 1 to a.Length - 1 {
            for k := j + 1 to a.Length - 1 {
                if (a[i] + a[j] + a[k]) % 3 == 0 {
                    count := count + 1;
                }
            }
        }
    }
    return count;
}
